from scipy.optimize import least_squares
models={
 'theta': lambda p: p[0]*P*(1-(P/p[1])**p[2]) - dP_dt,
 'allee': lambda p: p[0]*P*(1-P/p[1])*(P/p[2]-1)*0 + p[0]*P*(1-P/p[1])*(P+p[2])/(1+P) - dP_dt,
 'gompertz': lambda p: p[0]*P*np.log(p[1]/P) - dP_dt,
 'logistic_t': lambda p: (p[0]+p[2]*np.sin(p[3]*t))*P*(1-P/p[1]) - dP_dt,
 'sat': lambda p: p[0]*P*(1-P/p[1])-p[2]*P/(1+P)*0 - dP_dt,
}
for k,fn in models.items():
    best=None
    for s in [[1,5,1,0.5],[2,7,2,1],[0.5,4,0.5,0.2],[3,8,1.5,2]]:
        try:
            r=least_squares(fn,s)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    print(k,best.x, np.mean(best.fun**2)/np.var(dP_dt))
